"use client";

import { useRef } from "react";
import { motion, useReducedMotion } from "motion/react";
import "./fullscreen-menu.css";

export interface FullscreenMenuProps {
  links: { label: string; href: string }[];
  brand?: string;
}

/** Native dialog supplies focus trapping, Escape, and focus restoration. */
export function FullscreenMenu({
  links,
  brand = "Studio",
}: FullscreenMenuProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const reduce = useReducedMotion();
  return (
    <div className="forme-menu-demo">
      <span className="forme-menu-brand">
        {brand}
        <span>Independent by design.</span>
      </span>
      <button
        className="forme-menu-trigger"
        onClick={() => dialog.current?.showModal()}
        aria-haspopup="dialog"
      >
        Open menu<span aria-hidden="true">☰</span>
      </button>
      <span className="forme-menu-note">An entrance worth making.</span>
      <dialog
        ref={dialog}
        className="forme-menu-dialog"
        aria-label={`${brand} navigation`}
      >
        <div className="forme-menu-top">
          <span>{brand}</span>
          <button onClick={() => dialog.current?.close()} autoFocus>
            Close <span aria-hidden="true">×</span>
          </button>
        </div>
        <nav aria-label={`${brand} pages`}>
          {links.map((link, i) => (
            <motion.a
              key={link.href}
              href={link.href}
              onClick={() => dialog.current?.close()}
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              transition={{ delay: reduce ? 0 : i * 0.08 }}
            >
              <span>{link.label}</span>
              <span aria-hidden="true">↗</span>
            </motion.a>
          ))}
        </nav>
        <p>Built with intention. Made to move.</p>
      </dialog>
    </div>
  );
}

.forme-menu-demo {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
  min-height: 270px;
  height: 100%;
  box-sizing: border-box;
  padding: 24px;
  background: #ede8f7;
  color: #453069;
}
.forme-menu-brand {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 17px;
  letter-spacing: -0.04em;
}
.forme-menu-brand > span {
  font-size: 9px;
  letter-spacing: 0;
}
.forme-menu-trigger {
  display: flex;
  align-items: center;
  gap: 30px;
  border: 1px solid #45306955;
  border-radius: 50px;
  background: transparent;
  padding: 15px 22px;
  color: inherit;
  font: inherit;
  font-size: 17px;
  cursor: pointer;
}
.forme-menu-trigger > span {
  font-size: 19px;
}
.forme-menu-note {
  position: absolute;
  bottom: 25px;
  font-size: 10px;
}
.forme-menu-dialog {
  position: fixed;
  inset: 0;
  box-sizing: border-box;
  width: 100vw;
  height: 100dvh;
  max-width: none;
  max-height: none;
  margin: 0;
  border: 0;
  padding: clamp(24px, 6vw, 80px);
  background: #ede8f7;
  color: #453069;
  font-family: inherit;
}
.forme-menu-dialog::backdrop {
  background: #19132380;
}
.forme-menu-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 25px;
  letter-spacing: -0.04em;
}
.forme-menu-top button {
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 15px;
  cursor: pointer;
}
.forme-menu-top button span {
  font-size: 24px;
  margin-left: 15px;
}
.forme-menu-dialog nav {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 8vh 0 5vh;
}
.forme-menu-dialog nav a {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: center;
  font-size: clamp(32px, 7vw, 90px);
  line-height: 1.1;
  letter-spacing: -0.06em;
  color: inherit;
  text-decoration: none;
}
.forme-menu-dialog nav a > span:last-child {
  font-size: 0.5em;
}
.forme-menu-dialog nav a:hover {
  text-decoration: underline;
  text-underline-offset: 8px;
  text-decoration-thickness: 2px;
}
.forme-menu-dialog p {
  font-size: 13px;
}
.forme-menu-demo button:focus-visible,
.forme-menu-dialog :focus-visible {
  outline: 3px solid #2749ed;
  outline-offset: 5px;
}
